insert into public.announcements (id,title,body,category,pinned,department_id,author_id,created_at) values
('00000000-0000-4000-8000-000000001201','Good things happen when we get together','Our next all-hands is coming up. Join us for team updates, a look at what’s next, and a few well-deserved shout-outs. Bring your questions and your favorite coffee.','Company news',true,null,'00000000-0000-4000-8000-000000000009','2026-09-26T09:00:00+08:00'),
('00000000-0000-4000-8000-000000001202','A little time for your wellbeing','A reminder that your wellness days are here to be used. Take a breath, get outside, or do something that helps you recharge. Find the details in our Benefits & wellbeing guide.','People & culture',false,null,'00000000-0000-4000-8000-000000000017','2026-09-24T09:00:00+08:00'),
('00000000-0000-4000-8000-000000001203','Say hello to our newest teammates','Emma and James have joined Marketing and Sales. Help us give them a warm welcome and make their first weeks a little easier. We’re glad you’re here!','Team updates',false,null,'00000000-0000-4000-8000-000000000019','2026-09-22T09:00:00+08:00')
